/**
 * Supported inventory movement kinds.
 *
 * Attributes: OPENING: Stock present at the start of the period. PURCHASE:
 * Inbound inventory acquisition. COGS: Cost-of-goods-sold consumption. COUNT:
 * Adjustment to the physical count, modelled as a synthetic COGS movement
 * against the discrepancy.
 */
export type MovementKind = "opening" | "purchase" | "cogs" | "count";

/**
 * Digest-bound opaque evidence supporting a physical closing.
 */
export type PhysicalClosingEvidence = {
  reference: FilingEvidenceReference;
  role: PhysicalClosingEvidenceRole;
  content_digest: ContentDigest;
};

/**
 * Closed evidence roles required to ground a physical closing.
 */
export type PhysicalClosingEvidenceRole =
  "physical_count" | "acquisition_price_valuation";

/**
 * Digest-bound evidence of the immediately prior authoritative closing.
 */
export type PriorClosingContinuityEvidence = {
  reference: FilingEvidenceReference;
  content_digest: ContentDigest;
};

/**
 * What a purchase movement states about the ledger transaction that books it.
 *
 * A blank is never read as "not in the ledger": `UNSTATED` is its own state,
 * distinct from the operator's explicit `NONE`.
 *
 * Attributes: UNSTATED: Nothing is stated yet. CLAIMED: The movement claims
 * the named ledger transaction, which is then withheld from every Modelo 100
 * ledger expense destination. NONE: The operator states that no ledger
 * transaction books this purchase.
 */
export type PurchaseLedgerRow = "unstated" | "claimed" | "none";

/**
 * Supported inventory valuation methods.
 */
export type ValuationMethod = "fifo" | "pmp" | "coste_medio";

